xml.Script:
        Colors[ 0] := 'FFFF00'; 
        Colors[ 1] := 'FFFFFF'; 
        Colors[ 2] := '00FF00'; 
        Colors[ 3] := 'FF9A00'; 
        Colors[ 4] := 'FFB1DC'; 
        Colors[ 5] := '99CDFC'; 
        Colors[ 6] := 'CCFED0'; 
        Colors[ 7] := '969696';
        Colors[ 8] := 'CC99FF';
        Colors[ 9] := 'CD9900';
        Colors[10] := 'FF64CB';
        Colors[11] := 'CD9901'; 

        sColors[ 0] := '       220001              ';
        sColors[ 1] := '       00aaa0              ';
        sColors[ 2] := '       aaaaa0              ';
        sColors[ 3] := '       aa0005              ';
        sColors[ 4] := '       005555              ';
        sColors[ 5] := '       220000              ';

        sColors[ 6] := '333001 033300 777777 001004';
        sColors[ 7] := '000440 100044 000070 660444';
        sColors[ 8] := '333044 066604 999902 605000';
        sColors[ 9] := '000700 066604 999b02 605555';
        sColors[10] := '777777 800080 900060 660000';
        sColors[11] := '000000 888888 066666 004444';

        sColors[12] := '                     333001';
        sColors[13] := '                     000550';
        sColors[14] := '                     333050';
        sColors[15] := '                     000550';
        sColors[16] := '                     333004';
        sColors[17] := '                     000444';

        W := 0.5;
        N := 6;
        D := 2 * W / N;

        c := 0;
        for i := 0 to N do
            for j := 0 to N do
                for k := 0 to N do
                    if (i = 0) or (j = 0) or (k = 0) or (i = N) or (j = N) or (k = N) then begin
                        Vx[c] := D * i - W;
                        Vy[c] := D * j - W;
                        Vz[c] := D * k - W;
                        Idx[i,j,k] := IntToStr(c);
                        inc(c);
                    end;

        function GetSIdx(x2, y2, z2);
        begin
            Result := Idx[x2, y2, z2] + ';' + Idx[x2+dx2, y2+dy2, z2+dz2] + ';' + Idx[x2+dx1+dx2, y2+dy1+dy2, z2+dz1+dz2] + ';' + Idx[x2+dx1, y2+dy1, z2+dz1];
        end;

        function GetColor(x3, y3);
        begin
            substr := copy(sColors[y3], x3, 1);
            Result := Colors[HexToInt(substr)];
        end;

        procedure MakeSide(x, y, z, dx1, dy1, dz1, dx2, dy2, dz2, cx, cy);
        // x, y, z - left-top point of side
        // dx1, dy1, dz1 - 1st counting vector
        // dx2, dy2, dz2 - 2nd counting vector
        // cx, cy - left-top letter in sColors
        begin
            for i := 0 to N - 1 do begin
                for j := 0 to N - 1 do begin
                    S[c] := GetSIdx( x + dx1 * i + dx2 * j,  y + dy1 * i + dy2 * j,  z + dz1 * i + dz2 * j);
                    Cl[c] := GetColor(cx + i, cy + j);
                    Inc(c);
                end;
            end;
        end;

        c := 0;
        MakeSide( 0, N, N,  1, 0, 0,  0,-1, 0,   8, 0); // up
        MakeSide( 0, 0, N,  1, 0, 0,  0, 0,-1,   8, 6); // face
        MakeSide( 0, N, N,  0,-1, 0,  0, 0,-1,   1, 6); // left
        MakeSide( N, 0, N,  0, 1, 0,  0, 0,-1,  15, 6); // right
        MakeSide( N, N, N, -1, 0, 0,  0, 0,-1,  22, 6); // back
        MakeSide( N, N, 0, -1, 0, 0,  0,-1, 0,  22,12); // bottom
